1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "locality", expression = "java(locality(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    default String initials(Owner owner) {
30	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
31	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
32	    }
33	
34	    /** City -> canonical region, from the fixed city-to-region table. */
35	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
36	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
37	
38	    /**
39	     * The owner's locality (region), derived from city via the fixed city-to-region table
40	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD); {@code UNKNOWN} for any other city.
41	     */
42	    default String locality(Owner owner) {
43	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
44	    }
45	
46	    /**
47	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the last two
48	     * digits of the registrationDate year (e.g. {@code SYD-SMI-0007-M26}). Null when either the customer
49	     * code or the registration date is absent.
50	     */
51	    default String membershipNumber(Owner owner) {
52	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
53	            return null;
54	        }
55	        return String.format("%s-M%02d", owner.getCustomerCode(),
56	                owner.getRegistrationDate().getYear() % 100);
57	    }
58	
59	    /**
60	     * The owner's membership tier: {@code SILVER} when the owner's name was unique on creation
61	     * (namesakeCount is 0) and an email is present, otherwise {@code BRONZE}.
62	     */
63	    default OwnerDto.MembershipTierEnum membershipTier(Owner owner) {
64	        Integer namesakeCount = owner.getNamesakeCount();
65	        boolean unique = namesakeCount != null && namesakeCount == 0;
66	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
67	        return unique && hasEmail ? OwnerDto.MembershipTierEnum.SILVER
68	                : OwnerDto.MembershipTierEnum.BRONZE;
69	    }
70	
71	    Owner toOwner(OwnerDto ownerDto);
72	
73	    @Mapping(target = "id", ignore = true)
74	    @Mapping(target = "pets", ignore = true)
75	    Owner toOwner(OwnerFieldsDto ownerDto);
76	
77	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
78	
79	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
80	
81	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
82	        OwnerPageDto ownerPageDto = new OwnerPageDto();
83	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
84	        ownerPageDto.setPage(ownerPage.getNumber());
85	        ownerPageDto.setSize(ownerPage.getSize());
86	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
87	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
88	        return ownerPageDto;
89	    }
90	}
