19	 * predate the household are back-filled so both sides carry the shared id. An owner with no household
20	 * peer keeps a null {@code householdId}.
21	 */
22	public class AssignHouseholdId {
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
25	        String lastName = normalize(owner.getLastName());
26	        String address = OwnerAddress.normalize(owner.getAddress());
27	        List<Owner> household = new ArrayList<>();
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (lastName.equals(normalize(existing.getLastName()))
30	                    && address.equals(OwnerAddress.normalize(existing.getAddress()))) {
31	                household.add(existing);
32	            }
33	        }
34	        if (household.isEmpty()) {
35	            return; // no peer at this lastName + address, so no shared household
36	        }
37	        String householdId = deriveHouseholdId(lastName, address);
38	        owner.setHouseholdId(householdId);
39	        for (Owner existing : household) {
40	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
41	                existing.setHouseholdId(householdId);
42	                ownerRepository.save(existing);
43	            }
44	        }
45	    }
46	
47	    /** {@code H-} plus the first 12 upper-case hex chars of SHA-256(lastName + '|' + address). */
48	    private static String deriveHouseholdId(String lastName, String address) {
49	        try {
50	            byte[] digest = MessageDigest.getInstance("SHA-256")
51	                    .digest((lastName + '|' + address).getBytes(StandardCharsets.UTF_8));
52	            StringBuilder sb = new StringBuilder("H-");
53	            for (int i = 0; i < 6; i++) {
54	                sb.append(String.format("%02X", digest[i]));
55	            }
56	            return sb.toString();
57	        }
58	        catch (NoSuchAlgorithmException ex) {
59	            throw new IllegalStateException("SHA-256 not available", ex);
60	        }
61	    }
62	
63	    /** Lower-cased, trimmed, with runs of whitespace collapsed to a single space. */
64	    private static String normalize(String value) {
65	        if (value == null) {
66	            return "";
67	        }
68	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
69	    }
70	}
